/* Kök, çubuğun satır atlayan yüksekliğini yayla izler; yeni satır altındaki içeriği tek karede itmez. */
.root { position: relative; min-width: 0; }
.bar { position: relative; display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2) 6px; }

/* Küçük haplar: bir simge ve tablo hizalı bir sayı. Görüntüleyenin kendi tepkileri vurgu rengini ve dolu bir simge alır, durum yalnız renge dayanmaz. */
.pill, .add { position: relative; display: inline-flex; height: 32px; flex: none; align-items: center; margin: 0; border: 1px solid var(--border); border-radius: var(--radius-pill); background: var(--surface); color: var(--text-secondary); font: inherit; cursor: pointer; -webkit-tap-highlight-color: transparent; touch-action: manipulation; transition: background-color var(--duration-fast) var(--ease-standard), border-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
.pill { gap: 6px; padding: 0 11px 0 9px; font-size: var(--text-sm); font-weight: 500; line-height: 1; letter-spacing: var(--tracking-body); font-variant-numeric: tabular-nums; }
.pill[aria-pressed="true"] { border-color: color-mix(in oklab, var(--accent) 45%, var(--border)); background: var(--accent-subtle); color: var(--accent-strong); }
.pill[aria-pressed="true"] .icon svg { fill: color-mix(in oklab, currentColor 22%, transparent); }
.add { justify-content: center; width: 38px; padding: 0; color: var(--text-muted); }
.add[data-state="open"] { border-color: var(--border-strong); background: var(--surface-muted); color: var(--foreground); }
.pill:active { background: var(--surface-muted); }
.pill[aria-pressed="true"]:active { background: color-mix(in oklab, var(--accent) 18%, var(--surface)); }
.add:active { background: var(--surface-muted); color: var(--foreground); }
@media (hover: hover) and (pointer: fine) {
  .pill:hover, .add:hover { border-color: var(--border-strong); background: var(--surface-muted); color: var(--foreground); }
  .pill[aria-pressed="true"]:hover { border-color: color-mix(in oklab, var(--accent) 65%, var(--border)); background: color-mix(in oklab, var(--accent) 17%, var(--surface)); color: var(--accent-strong); }
  .pill:hover .tip, .add:hover .tip { opacity: 1; transform: translate(-50%, 0); transition-delay: .45s; }
  .pill:hover, .add:hover { z-index: 2; }
}
.pill:focus-visible, .add:focus-visible { z-index: 2; }
.pill:focus-visible .tip { opacity: 1; transform: translate(-50%, 0); transition-delay: .2s; }

.icon, .addIcon { display: grid; width: 16px; height: 16px; flex: none; place-items: center; }
.addGlyph { display: grid; grid-area: 1 / 1; place-items: center; }
/* Sayı penceresi rakamlarına sarılır, rakam eklenince yaylanır; çıkan rakamlar akıştan ayrılır, genişlik hemen izler. */
.count { display: inline-flex; min-width: 0; }
.digits { position: relative; display: inline-flex; width: max-content; }
.digit { display: inline-block; }

/* Etiket kısa bir üzerine gelmeden sonra ya da klavye odağında görünür. Yüzer, bu yüzden hafif bir gölgeyi hak eder. */
.tip { position: absolute; bottom: calc(100% + 8px); left: 50%; z-index: 1; padding: 5px 9px; border: 1px solid var(--border); border-radius: var(--radius-pill); background: var(--surface-raised); box-shadow: var(--shadow-raised); color: var(--foreground); font-size: var(--text-xs); font-weight: 400; line-height: 1.2; letter-spacing: var(--tracking-body); white-space: nowrap; pointer-events: none; opacity: 0; transform: translate(-50%, 3px); transition: opacity var(--duration-instant) var(--ease-standard), transform var(--duration-fast) var(--ease-standard); }

/* Seçici ekleme düğmesinden büyür: Radix dönüşüm başlangıcını düğmenin merkezine koyar. */
.picker { z-index: 60; display: grid; gap: 2px; padding: 5px; border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface-raised); box-shadow: var(--shadow-floating); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); transform-origin: var(--radix-popover-content-transform-origin); outline: none; }
.picker[data-state="closed"] { pointer-events: none; }
.arrow { visibility: hidden; }
.options { position: relative; isolation: isolate; display: flex; gap: 2px; }
.highlight { position: absolute; top: 0; left: 0; z-index: -1; width: 40px; height: 40px; border-radius: var(--radius-pill); background: var(--surface-muted); }
.option { position: relative; display: grid; width: 40px; height: 40px; flex: none; place-items: center; padding: 0; border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--text-secondary); cursor: pointer; -webkit-tap-highlight-color: transparent; transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard); }
/* Seçilen seçenekler tonun yanında halka da taşır, böylece üzerine gelme vurgusu gibi okunmaz. */
.option[aria-pressed="true"] { background: var(--accent-subtle); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent); color: var(--accent-strong); }
.option[aria-pressed="true"] svg { fill: color-mix(in oklab, currentColor 22%, transparent); }
@media (hover: hover) and (pointer: fine) { .option:hover { color: var(--foreground); } .option[aria-pressed="true"]:hover { color: var(--accent-strong); } }
.optionIcon { display: grid; place-items: center; }
.caption { position: relative; display: flex; height: 22px; align-items: center; justify-content: center; color: var(--text-secondary); font-size: var(--text-xs); line-height: 1; }
.captionText { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; }
.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@media (prefers-reduced-motion: reduce) { .pill, .add, .option, .tip { transition: none; } }

"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState, useSyncExternalStore } from "react";
import type { KeyboardEvent as ReactKeyboardEvent, RefObject } from "react";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import { AnimatePresence, LayoutGroup, animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import type { AnimationPlaybackControls, TargetAndTransition, Transition, Variants } from "motion/react";
import { Check, SmilePlus, X } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { motionTokens } from "../lib/motion-tokens";
import { formatCompact, formatNumber } from "../lib/chart-format";
import styles from "./reactions.module.css";

/**
 * Yorumlar, gönderiler ve sürüm notları için tepki çubuğu. Her hap bir tepkiyi ve onu seçen kişi sayısını gösterir; görüntüleyenin kendi tepkileri vurgu rengini taşır.
 * Hapa dokunmak görüntüleyenin tepkisini ekler ya da kaldırır; ekleme düğmesi kendisinden büyüyen küçük bir seçici açar. Hızlı onay için kullan;
 * insanların özel bir şey söylemesi gerekiyorsa yanıt alanı ver.
 */
export interface ReactionOption { id: string; label: string; icon: LucideIcon }
export interface Reaction { id: string; count: number; reacted: boolean }
export interface ReactionsProps {
  /** Seçicinin sunduğu bütün tepkiler, seçici sırasıyla. */
  options: ReactionOption[];
  /** Denetimli tepkiler. Haplar bu sırayı korur, sayısı sıfıra inen tepki çubuktan çıkar. */
  value?: Reaction[];
  defaultValue?: Reaction[];
  /** Sonraki tepkilerle ve onları doğuran değişiklikle çağrılır. */
  onValueChange?: (next: Reaction[], change: { id: string; reacted: boolean }) => void;
  /** Çubuğun erişilebilir adı. */
  label?: string;
  className?: string;
}

const enter = [...motionTokens.ease.enter] as [number, number, number, number];
const standard = [...motionTokens.ease.standard] as [number, number, number, number];
const blur = (px: number) => `blur(${px}px)`;
const noop = () => () => {};

/** Azaltılmış hareket yalnız hidrasyondan sonra sayılır, böylece sunucu ile ilk istemci çizimi hep uyuşur. */
function useReduced() {
  const hydrated = useSyncExternalStore(noop, () => true, () => false);
  const reduced = useReducedMotion() ?? false;
  return hydrated && reduced;
}

/** `content` öğesinin doğal boyutunu izler: `key` değişince boyut ona yaylanır; başka her yeniden boyutlanma (geç gelen yazı tipi, yeniden akış) atlar, açılışta hiçbir şey sallanmaz. */
function useFollowSize(content: RefObject<HTMLElement | null>, axis: "width" | "height", key: string, reduced: boolean, transition: Transition) {
  const size = useMotionValue<number | "auto">("auto");
  const lastKey = useRef(key), armedUntil = useRef(0);
  useLayoutEffect(() => {
    if (lastKey.current === key) return;
    lastKey.current = key;
    armedUntil.current = performance.now() + 700;
  }, [key]);
  useEffect(() => {
    const node = content.current;
    if (!node || typeof ResizeObserver === "undefined") return;
    let measured = false;
    let sizing: AnimationPlaybackControls | undefined;
    // Kenarlık kutusu boyutları dönüşümleri yok sayar, bu yüzden hâlâ ölçeklenerek giren hap gerçek genişliğini bildirir.
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return;
      const box = entry.borderBoxSize?.[0];
      const next = box ? (axis === "width" ? box.inlineSize : box.blockSize) : axis === "width" ? node.offsetWidth : node.offsetHeight;
      sizing?.stop();
      if (!measured || reduced || performance.now() > armedUntil.current) { measured = true; size.jump(next); return; }
      sizing = animate(size, next, transition);
    });
    observer.observe(node, { box: "border-box" });
    return () => { observer.disconnect(); sizing?.stop(); };
  }, [axis, content, reduced, size, transition]);
  return size;
}

/** Rakamlar sayının gittiği yöne döner: artınca yukarı çıkar, azalınca aşağı iner. Yalnız değişen rakamlar hareket eder. */
const digitMotion: Variants = {
  enter: (direction: number) => ({ opacity: 0, y: `${direction * .55}em`, filter: blur(motionTokens.blur.subtle) }),
  center: { opacity: 1, y: "0em", filter: blur(0) },
  exit: (direction: number) => ({ opacity: 0, y: `${direction * -.55}em`, filter: blur(motionTokens.blur.subtle), transition: { duration: motionTokens.duration.fast, ease: standard } }),
};
const digitStill: Variants = { enter: { opacity: 1 }, center: { opacity: 1 }, exit: { opacity: 0, transition: { duration: 0 } } };
const digitTransition = { y: motionTokens.spring.snappy, opacity: { duration: motionTokens.duration.fast, ease: enter }, filter: { duration: motionTokens.duration.fast, ease: enter } };

function RollingCount({ value, reduced }: { value: number; reduced: boolean }) {
  const [roll, setRoll] = useState({ value, direction: 1 });
  if (roll.value !== value) setRoll({ value, direction: value > roll.value ? 1 : -1 });
  const row = useRef<HTMLSpanElement>(null);
  // Türkçe yazım: 1234 → "1,2B"; binin altı olduğu gibi yazılır (ABACUS).
  const text = formatCompact(value);
  const width = useFollowSize(row, "width", text, reduced, motionTokens.spring.morph);
  return <motion.span className={styles.count} style={{ width }} aria-hidden="true">
    <span ref={row} className={styles.digits}>
      <AnimatePresence mode="popLayout" initial={false} custom={roll.direction}>
        {[...text].map((digit, index) => <motion.span key={`${text.length - index}:${digit}`} className={styles.digit} custom={roll.direction} variants={reduced ? digitStill : digitMotion}
          initial="enter" animate="center" exit="exit" transition={reduced ? { duration: 0 } : digitTransition}>{digit}</motion.span>)}
      </AnimatePresence>
    </span>
  </motion.span>;
}

/** Anahtar kare değil bir itki: simge hızla dinlenme konumundan başlar, aşar ve oturur. Hızlı ikinci dokunuş hareketi baştan başlatmaz, üstüne ekler. */
const kick = { type: "spring", stiffness: 420, damping: 17 } as const;

function KickIcon({ icon: Icon, pop, reduced }: { icon: LucideIcon; pop: number; reduced: boolean }) {
  const scale = useMotionValue(1), rotate = useMotionValue(0);
  const seen = useRef(0);
  useEffect(() => {
    if (pop <= seen.current) return;
    seen.current = pop;
    if (reduced) return;
    animate(scale, 1, { ...kick, velocity: scale.getVelocity() + 11 });
    animate(rotate, 0, { ...kick, velocity: rotate.getVelocity() - 420 });
  }, [pop, reduced, rotate, scale]);
  useEffect(() => () => { scale.stop(); rotate.stop(); }, [rotate, scale]);
  return <motion.span className={styles.icon} style={{ scale, rotate }} aria-hidden="true"><Icon size={16} strokeWidth={1.75} /></motion.span>;
}

const rest: TargetAndTransition = { opacity: 1, scale: 1, y: 0, filter: blur(0) };
const fadeIn: TargetAndTransition = { opacity: 0 };
const fadeOut: TargetAndTransition = { opacity: 0, transition: { duration: motionTokens.duration.instant } };
const pillIn: TargetAndTransition = { opacity: 0, scale: .5, filter: blur(motionTokens.blur.soft) };
const pillOut: TargetAndTransition = { opacity: 0, scale: .6, filter: blur(motionTokens.blur.subtle), transition: { duration: motionTokens.duration.fast, ease: standard } };
const pillTransition = { layout: motionTokens.spring.morph, scale: motionTokens.spring.snappy, opacity: { duration: motionTokens.duration.fast, ease: enter }, filter: { duration: motionTokens.duration.fast, ease: enter } };
const iconIn: TargetAndTransition = { opacity: 0, scale: .6, filter: blur(motionTokens.blur.subtle) };
const iconOut: TargetAndTransition = { ...iconIn, transition: { duration: motionTokens.duration.fast, ease: standard } };
const iconEnter = { ...motionTokens.spring.snappy, opacity: { duration: motionTokens.duration.fast, ease: enter }, filter: { duration: motionTokens.duration.fast, ease: enter } };
const textIn: TargetAndTransition = { opacity: 0, y: "0.3em", filter: blur(motionTokens.blur.soft) };
const textOut: TargetAndTransition = { opacity: 0, y: "-0.3em", filter: blur(motionTokens.blur.subtle), transition: { duration: motionTokens.duration.fast, ease: standard } };

/** Bütün seçeneklerin tepsisi. Ortak bir vurgu üzerine gelinen ya da odaklanan seçeneğe kayar, bir alt yazı onu adlandırır; simge kendini açıklamak zorunda kalmaz. */
function Picker({ options, reacted, reduced, onPick }: { options: ReactionOption[]; reacted: Set<string>; reduced: boolean; onPick: (id: string) => void }) {
  const [focusIndex, setFocusIndex] = useState(0);
  const [hovered, setHovered] = useState<number | null>(null);
  const active = Math.min(hovered ?? focusIndex, options.length - 1);
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const x = useMotionValue(0);
  const placed = useRef(false);
  useLayoutEffect(() => {
    const target = buttons.current[active]?.offsetLeft ?? 0;
    if (!placed.current || reduced) { placed.current = true; x.jump(target); return; }
    // Yeni hedef çalışan yayı yeniden hedefler ve hızını korur; hızlı süpürme adım adım değil süzülerek gider.
    animate(x, target, motionTokens.spring.morph);
  }, [active, reduced, x]);
  useEffect(() => () => x.stop(), [x]);

  function onKeyDown(event: ReactKeyboardEvent<HTMLDivElement>) {
    const steps: Record<string, number> = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
    const count = options.length;
    const next = event.key in steps ? (focusIndex + steps[event.key]! + count) % count : event.key === "Home" ? 0 : event.key === "End" ? count - 1 : -1;
    if (next < 0) return;
    event.preventDefault();
    setHovered(null);
    setFocusIndex(next);
    buttons.current[next]?.focus();
  }

  const option = options[active];
  const chosen = option ? reacted.has(option.id) : false;
  return <>
    <div className={styles.options} role="toolbar" aria-label="Tepkiler" aria-orientation="horizontal" onKeyDown={onKeyDown} onPointerLeave={() => setHovered(null)}>
      <motion.span className={styles.highlight} style={{ x }} aria-hidden="true" />
      {options.map((item, index) => {
        const Icon = item.icon;
        const lit = index === active;
        return <motion.button key={item.id} ref={node => { buttons.current[index] = node; }} type="button" className={styles.option} aria-label={item.label} aria-pressed={reacted.has(item.id)} tabIndex={index === focusIndex ? 0 : -1}
          onFocus={() => setFocusIndex(index)} onPointerMove={event => { if (event.pointerType === "mouse" && hovered !== index) setHovered(index); }} onClick={() => onPick(item.id)}
          initial={reduced ? fadeIn : iconIn} animate={rest} transition={reduced ? { duration: motionTokens.duration.fast } : { ...iconEnter, delay: .04 + index * motionTokens.stagger.item, opacity: { ...iconEnter.opacity, delay: .04 + index * motionTokens.stagger.item }, filter: { ...iconEnter.filter, delay: .04 + index * motionTokens.stagger.item } }}>
          <motion.span className={styles.optionIcon} animate={{ scale: lit && !reduced ? 1.14 : 1, y: lit && !reduced ? -1 : 0 }} transition={motionTokens.spring.snappy}><Icon size={20} strokeWidth={1.75} aria-hidden="true" /></motion.span>
        </motion.button>;
      })}
    </div>
    <div className={styles.caption} aria-hidden="true">
      <AnimatePresence mode="popLayout" initial={false}>
        {option && <motion.span key={`${option.id}:${chosen}`} className={styles.captionText} initial={reduced ? fadeIn : textIn} animate={rest} exit={reduced ? fadeOut : textOut} transition={{ duration: reduced ? motionTokens.duration.fast : motionTokens.duration.standard, ease: enter }}>
          {chosen && <Check size={12} strokeWidth={2} />}{option.label}
        </motion.span>}
      </AnimatePresence>
    </div>
  </>;
}

export function Reactions({ options, value, defaultValue = [], onValueChange, label = "Tepkiler", className }: ReactionsProps) {
  const reduced = useReduced();
  const groupId = useId();
  const [own, setOwn] = useState(defaultValue);
  const list = value ?? own;
  const [pops, setPops] = useState<Record<string, number>>({});
  const [announcement, setAnnouncement] = useState("");
  const [open, setOpen] = useState(false);
  const bar = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const refocus = useRef<string | null>(null);
  const byId = new Map(options.map(option => [option.id, option]));
  const shown = list.filter(reaction => reaction.count > 0 && byId.has(reaction.id));
  const reacted = new Set(shown.filter(reaction => reaction.reacted).map(reaction => reaction.id));
  // Yeni satıra sarmak çubuğun yüksekliğini değiştirir; yükseklik altındaki içeriği itmek yerine yayla izler.
  const height = useFollowSize(bar, "height", shown.map(reaction => `${reaction.id}${reaction.count}`).join(), reduced, motionTokens.spring.smooth);

  // Odaktayken ayrılan hap odağı komşusuna ya da ekleme düğmesine verir, klavye kullanıcısı sayfaya düşmez.
  useLayoutEffect(() => {
    const target = refocus.current;
    if (!target) return;
    refocus.current = null;
    const next = target === "add" ? trigger.current : bar.current?.querySelector<HTMLElement>(`[data-reaction="${CSS.escape(target)}"]`);
    next?.focus();
  });

  function toggle(id: string) {
    const option = byId.get(id);
    if (!option) return;
    const current = shown.find(reaction => reaction.id === id);
    const add = !current?.reacted;
    const count = Math.max(0, (current?.count ?? 0) + (add ? 1 : -1));
    const next = current ? list.map(reaction => reaction.id === id ? { ...reaction, count, reacted: add } : reaction).filter(reaction => reaction.count > 0) : [...list.filter(reaction => reaction.id !== id), { id, count: 1, reacted: true }];
    if (count === 0) {
      const pill = bar.current?.querySelector(`[data-reaction="${CSS.escape(id)}"]`);
      if (pill && pill === document.activeElement) {
        const index = shown.findIndex(reaction => reaction.id === id);
        refocus.current = shown[index + 1]?.id ?? shown[index - 1]?.id ?? "add";
      }
    }
    if (add) setPops(previous => ({ ...previous, [id]: (previous[id] ?? 0) + 1 }));
    if (value === undefined) setOwn(next);
    setAnnouncement(add ? `${option.label} eklendi. ${formatNumber(count, 0)} tepki.` : count ? `${option.label} kaldırıldı. ${formatNumber(count, 0)} tepki.` : `${option.label} kaldırıldı.`);
    onValueChange?.(next, { id, reacted: add });
  }

  function pick(id: string) {
    setOpen(false);
    trigger.current?.focus();
    toggle(id);
  }

  return <motion.div className={[styles.root, className].filter(Boolean).join(" ")} style={{ height }}>
    <div ref={bar} className={styles.bar} role="group" aria-label={label}>
      <LayoutGroup id={groupId}>
        <AnimatePresence mode="popLayout" initial={false}>
          {shown.map(reaction => {
            const option = byId.get(reaction.id)!;
            return <motion.button key={reaction.id} layout="position" type="button" className={styles.pill} data-reaction={reaction.id} aria-pressed={reaction.reacted}
              aria-label={`${option.label}, ${formatNumber(reaction.count, 0)} tepki${reaction.reacted ? ", seninki dahil" : ""}`} onClick={() => toggle(reaction.id)}
              initial={reduced ? fadeIn : pillIn} animate={rest} exit={reduced ? fadeOut : pillOut} whileTap={{ scale: reduced ? 1 : .97 }}
              transition={reduced ? { duration: motionTokens.duration.fast, layout: { duration: 0 } } : pillTransition}>
              <KickIcon icon={option.icon} pop={pops[reaction.id] ?? 0} reduced={reduced} />
              <RollingCount value={reaction.count} reduced={reduced} />
              <span className={styles.tip} aria-hidden="true">{option.label}</span>
            </motion.button>;
          })}
        </AnimatePresence>
        <PopoverPrimitive.Root open={open} onOpenChange={setOpen}>
          {/* Ekleme düğmesi seçiciyi bağlar, bu yüzden basmaya renkle yanıt verir, hiç ölçeklenmez. */}
          <PopoverPrimitive.Trigger asChild>
            <motion.button ref={trigger} layout="position" transition={reduced ? { layout: { duration: 0 } } : { layout: motionTokens.spring.morph }} type="button" className={styles.add} aria-label="Tepki ekle">
              <span className={styles.addIcon} aria-hidden="true">
                <AnimatePresence initial={false}>
                  <motion.span key={open ? "close" : "add"} className={styles.addGlyph} initial={reduced ? fadeIn : iconIn} animate={rest} exit={reduced ? fadeOut : iconOut} transition={reduced ? { duration: motionTokens.duration.fast } : iconEnter}>
                    {open ? <X size={16} strokeWidth={1.75} /> : <SmilePlus size={16} strokeWidth={1.75} />}
                  </motion.span>
                </AnimatePresence>
              </span>
              {!open && <span className={styles.tip} aria-hidden="true">Tepki ekle</span>}
            </motion.button>
          </PopoverPrimitive.Trigger>
          <AnimatePresence>
            {open && <PopoverPrimitive.Portal forceMount>
              {/* Odak elle geri verilir: seçimden ya da Escape'ten sonra hemen, dışarı tıklanınca hiç. */}
              <PopoverPrimitive.Content forceMount asChild side="top" align="center" sideOffset={8} collisionPadding={12} aria-label="Bir tepki ekle"
                onEscapeKeyDown={() => trigger.current?.focus()} onCloseAutoFocus={event => event.preventDefault()}>
                <motion.div className={styles.picker} initial={reduced ? fadeIn : { opacity: 0, scale: .5, filter: blur(motionTokens.blur.soft) }} animate={rest}
                  exit={reduced ? fadeOut : { opacity: 0, scale: .9, filter: blur(motionTokens.blur.subtle), transition: { duration: motionTokens.duration.fast, ease: standard } }}
                  transition={reduced ? { duration: motionTokens.duration.fast } : { scale: motionTokens.spring.snappy, opacity: { duration: motionTokens.duration.fast, ease: standard }, filter: { duration: motionTokens.duration.fast, ease: enter } }}>
                  {/* Görünmez ok Radix'in dönüşüm başlangıcını düğmenin merkezine koymasını sağlar; tepsi ekranda kalmak için kaysa da düğmeden büyür. */}
                  <PopoverPrimitive.Arrow width={0} height={0} className={styles.arrow} />
                  <Picker options={options} reacted={reacted} reduced={reduced} onPick={pick} />
                </motion.div>
              </PopoverPrimitive.Content>
            </PopoverPrimitive.Portal>}
          </AnimatePresence>
        </PopoverPrimitive.Root>
      </LayoutGroup>
    </div>
    <span className={styles.srOnly} role="status">{announcement}</span>
  </motion.div>;
}

export default Reactions;
